package com.secure.documentwallet;

import android.content.Intent;
import android.graphics.*;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import androidx.fragment.app.FragmentActivity;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** Full-proportion virtual card wallet with flip and downward-flick navigation. */
public class BankCardActivity extends FragmentActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private final ArrayList<JSONObject> cards=new ArrayList<>();
 private VaultRepository repo;private JSONObject document;private Bitmap front,back,rearNearImage,rearDeepImage;
 private FrameLayout card,rearNear,rearDeep;private TextView title,sideLabel,counter;private int cardIndex;private boolean showingBack,ready;private float touchDownY;

 @Override public void onCreate(Bundle state){super.onCreate(state);Ui.safeScreen(this);Ui.lightBars(this);if(!Session.valid()){finish();return;}repo=new VaultRepository(this);buildPage();loadWallet(getIntent().getStringExtra("id"));}
 private void buildPage(){
  LinearLayout page=Ui.column(this);page.setBackgroundColor(Ui.BG);page.setPadding(Ui.dp(this,18),Ui.dp(this,14),Ui.dp(this,18),Ui.dp(this,25));
  LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);TextView backButton=Ui.text(this,"‹",40,Ui.NAVY);backButton.setGravity(Gravity.CENTER);backButton.setContentDescription("Back To Bank Cards");backButton.setOnClickListener(v->finish());bar.addView(backButton,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,54)));
  ImageView categoryIcon=new ImageView(this);categoryIcon.setImageResource(R.drawable.ic_bank_card);categoryIcon.setPadding(Ui.dp(this,8),Ui.dp(this,8),Ui.dp(this,8),Ui.dp(this,8));categoryIcon.setBackground(Ui.bg(DocumentGroups.color(DocumentGroups.CARDS),Ui.dp(this,28)));bar.addView(categoryIcon,new LinearLayout.LayoutParams(Ui.dp(this,52),Ui.dp(this,52)));
  LinearLayout titles=Ui.column(this);titles.setPadding(Ui.dp(this,13),0,0,0);TextView heading=Ui.title(this,"Bank Cards",25);heading.setTextColor(Ui.NAVY);titles.addView(heading);counter=Ui.text(this,"Opening Encrypted Wallet…",13,0xff727a87);titles.addView(counter);bar.addView(titles,new LinearLayout.LayoutParams(0,-2,1));page.addView(bar);
  TextView instruction=Ui.text(this,"Tap To Flip  ·  Flick Down For Next",14,Ui.TEAL);instruction.setTypeface(null,android.graphics.Typeface.BOLD);instruction.setGravity(Gravity.CENTER);instruction.setPadding(0,Ui.dp(this,20),0,Ui.dp(this,12));page.addView(instruction);
  int availableDp=Math.round(getResources().getDisplayMetrics().widthPixels/getResources().getDisplayMetrics().density)-46,faceHeight=Ui.dp(this,Math.round(availableDp/1.586f));
  FrameLayout deck=new FrameLayout(this);deck.setClipChildren(false);rearDeep=layer(.56f,.91f,31);rearNear=layer(.78f,.96f,17);deck.addView(rearDeep,params(faceHeight,18));deck.addView(rearNear,params(faceHeight,9));
  card=new FrameLayout(this);card.setBackground(Ui.stroke(Color.WHITE,Ui.dp(this,1),Ui.GOLD,Ui.dp(this,22)));card.setClipToOutline(true);card.setElevation(Ui.dp(this,11));card.setCameraDistance(Ui.dp(this,9000));card.setOnClickListener(v->flip());card.setOnTouchListener((v,e)->{if(e.getActionMasked()==MotionEvent.ACTION_DOWN){touchDownY=e.getY();return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP){if(e.getY()-touchDownY>Ui.dp(this,58))nextCard();else v.performClick();return true;}return true;});deck.addView(card,params(faceHeight,0));page.addView(deck,new LinearLayout.LayoutParams(-1,faceHeight+Ui.dp(this,42)));
  title=Ui.title(this,"",20);title.setTextColor(Ui.NAVY);title.setGravity(Gravity.CENTER);page.addView(title);sideLabel=Ui.text(this,"Loading Secure Card…",13,Ui.MUTED);sideLabel.setGravity(Gravity.CENTER);sideLabel.setPadding(0,Ui.dp(this,4),0,0);page.addView(sideLabel);
  TextView privacy=Ui.text(this,"The full card remains visible at its natural proportions. Tap to turn it over, or flick down to bring the next card forward.",13,Ui.MUTED);privacy.setGravity(Gravity.CENTER);privacy.setLineSpacing(0,1.12f);privacy.setPadding(Ui.dp(this,16),Ui.dp(this,17),Ui.dp(this,16),Ui.dp(this,18));page.addView(privacy);
  TextView details=Ui.pill(this,"Edit, Recrop And Export",Ui.TEAL);details.setOnClickListener(v->{if(document!=null)startActivity(new Intent(this,DocumentActivity.class).putExtra("id",document.optString("id")));});page.addView(details,new LinearLayout.LayoutParams(-1,Ui.dp(this,52)));setContentView(page);
 }
 private FrameLayout layer(float alpha,float scale,int drop){FrameLayout v=new FrameLayout(this);v.setBackground(Ui.stroke(0xffe8f6fc,Ui.dp(this,1),0xffb8d4da,Ui.dp(this,22)));v.setClipToOutline(true);v.setAlpha(alpha);v.setScaleX(scale);v.setTranslationY(Ui.dp(this,drop));v.setElevation(Ui.dp(this,3));return v;}
 private FrameLayout.LayoutParams params(int h,int top){FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(-1,h,Gravity.TOP|Gravity.CENTER_HORIZONTAL);p.setMargins(Ui.dp(this,5),Ui.dp(this,top),Ui.dp(this,5),0);return p;}
 private void loadWallet(String requestedId){ready=false;io.execute(()->{try{JSONArray all=repo.all();cards.clear();int selected=0;for(int i=0;i<all.length();i++){JSONObject item=all.optJSONObject(i);if(item==null||!DocumentGroups.CARDS.equals(DocumentGroups.fromCategory(item.optString("category"))))continue;if(requestedId!=null&&requestedId.equals(item.optString("id")))selected=cards.size();cards.add(item);}if(cards.isEmpty())throw new IllegalStateException("No Bank Cards Are Available");cardIndex=selected;runOnUiThread(()->loadCurrent(false));}catch(Exception error){runOnUiThread(()->showError(error.getMessage()));}});}
 private void loadCurrent(boolean animate){if(cards.isEmpty())return;ready=false;showingBack=false;releaseImages();card.removeAllViews();rearNear.removeAllViews();rearDeep.removeAllViews();document=cards.get(cardIndex);title.setText(document.optString("title","Bank Card"));counter.setText((cardIndex+1)+" Of "+cards.size());if(animate){card.setAlpha(0);card.setTranslationY(-Ui.dp(this,42));card.setRotation(-4);}ProgressBar loading=new ProgressBar(this);card.addView(loading,new FrameLayout.LayoutParams(Ui.dp(this,46),Ui.dp(this,46),Gravity.CENTER));final int requested=cardIndex;io.execute(()->{try{JSONArray pages=document.optJSONArray("pages");if(pages==null||pages.length()==0)throw new IllegalStateException("No Card Image Was Saved");Bitmap[] decoded=new Bitmap[4];decoded[0]=decode(repo.page(document,0));if(pages.length()>1)decoded[1]=decode(repo.page(document,1));if(cards.size()>1)decoded[2]=decode(repo.page(cards.get((requested+1)%cards.size()),0));if(cards.size()>2)decoded[3]=decode(repo.page(cards.get((requested+2)%cards.size()),0));runOnUiThread(()->{if(isFinishing()||requested!=cardIndex){for(Bitmap b:decoded)if(b!=null)b.recycle();return;}front=decoded[0];back=decoded[1];rearNearImage=decoded[2];rearDeepImage=decoded[3];putRear(rearNear,rearNearImage);putRear(rearDeep,rearDeepImage);ready=true;showSide(false);if(animate)card.animate().alpha(1).translationY(0).rotation(0).setDuration(285).start();});}catch(Exception e){runOnUiThread(()->showError(e.getMessage()));}});}
 private Bitmap decode(byte[] raw){BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(raw,0,raw.length,bounds);int s=1;while(Math.max(bounds.outWidth,bounds.outHeight)/s>1800)s*=2;BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=s;return BitmapFactory.decodeByteArray(raw,0,raw.length,o);}
 private void putRear(FrameLayout frame,Bitmap bitmap){frame.removeAllViews();if(bitmap==null)return;ImageView image=new ImageView(this);image.setImageBitmap(bitmap);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setBackgroundColor(Color.WHITE);frame.addView(image,new FrameLayout.LayoutParams(-1,-1));}
 private void showSide(boolean backSide){card.removeAllViews();Bitmap image=backSide?back:front;if(image!=null){ImageView view=new ImageView(this);view.setImageBitmap(image);view.setScaleType(ImageView.ScaleType.FIT_CENTER);view.setBackgroundColor(Color.WHITE);card.addView(view,new FrameLayout.LayoutParams(-1,-1));}else{LinearLayout missing=Ui.column(this);missing.setGravity(Gravity.CENTER);missing.setBackground(Ui.bg(0xff0e6f69,Ui.dp(this,22)));TextView stripe=new TextView(this);stripe.setBackgroundColor(0xff203f49);missing.addView(stripe,new LinearLayout.LayoutParams(-1,Ui.dp(this,42)));TextView message=Ui.text(this,"No Back Image Was Saved",17,Color.WHITE);message.setGravity(Gravity.CENTER);message.setTypeface(null,android.graphics.Typeface.BOLD);missing.addView(message,new LinearLayout.LayoutParams(-1,0,1));card.addView(missing,new FrameLayout.LayoutParams(-1,-1));}TextView badge=Ui.text(this,backSide?"BACK":"FRONT",11,Color.WHITE);badge.setGravity(Gravity.CENTER);badge.setTypeface(null,android.graphics.Typeface.BOLD);badge.setBackground(Ui.bg(0xdd061f3b,Ui.dp(this,12)));FrameLayout.LayoutParams bp=new FrameLayout.LayoutParams(Ui.dp(this,68),Ui.dp(this,26),Gravity.TOP|Gravity.END);bp.setMargins(0,Ui.dp(this,12),Ui.dp(this,12),0);card.addView(badge,bp);sideLabel.setText(backSide?"Back Of Card":"Front Of Card");}
 private void flip(){if(!ready||!card.isEnabled())return;card.setEnabled(false);card.animate().rotationY(90).setDuration(165).withEndAction(()->{showingBack=!showingBack;showSide(showingBack);card.setRotationY(-90);card.animate().rotationY(0).setDuration(190).withEndAction(()->card.setEnabled(true)).start();}).start();}
 private void nextCard(){if(!ready||cards.size()<2){card.animate().translationY(Ui.dp(this,12)).setDuration(90).withEndAction(()->card.animate().translationY(0).setDuration(120).start()).start();return;}ready=false;card.animate().translationY(Ui.dp(this,360)).rotation(7).alpha(0).setDuration(235).withEndAction(()->{cardIndex=(cardIndex+1)%cards.size();loadCurrent(true);}).start();}
 private void showError(String message){ready=false;card.removeAllViews();TextView error=Ui.text(this,message==null?"Could Not Open This Card":message,15,0xffb3261e);error.setGravity(Gravity.CENTER);card.addView(error,new FrameLayout.LayoutParams(-1,-1));sideLabel.setText("Card Unavailable");}
 private void releaseImages(){for(Bitmap b:new Bitmap[]{front,back,rearNearImage,rearDeepImage})if(b!=null&&!b.isRecycled())b.recycle();front=back=rearNearImage=rearDeepImage=null;}
 @Override public boolean dispatchTouchEvent(MotionEvent e){if(Session.valid())Session.touch();return super.dispatchTouchEvent(e);}
 @Override protected void onResume(){super.onResume();if(!Session.valid())finish();else if(!cards.isEmpty())loadWallet(document==null?null:document.optString("id"));}
 @Override protected void onDestroy(){super.onDestroy();io.shutdownNow();releaseImages();}
}
